            ["ZRANGEBYLEX"] = (ReadCommandKind.Read, -1),
            ["ZRANGEBYSCORE"] = (ReadCommandKind.Read, -1),
            ["ZRANK"] = (ReadCommandKind.Read, -1),
            ["ZREVRANGE"] = (ReadCommandKind.Read, -1),
            ["ZREVRANGEBYLEX"] = (ReadCommandKind.Read, -1),
            ["ZREVRANGEBYSCORE"] = (ReadCommandKind.Read, -1),
            ["ZREVRANK"] = (ReadCommandKind.Read, -1),
            ["ZSCAN"] = (ReadCommandKind.CursorRead, 1),
            ["ZSCORE"] = (ReadCommandKind.Read, -1),
            ["ZUNION"] = (ReadCommandKind.Read, -1),
        }.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);

    internal static (ReadCommandKind Kind, int CursorArgumentIndex) Get(string command)
        => s_commands.TryGetValue(command, out var metadata) ? metadata : (ReadCommandKind.None, -1);
}

